/// <summary>
/// Extends SysOperationServiceController
/// </summary>
internal final class AVACRLProtractedDefaultController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Main method
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    AVACRLProtractedDefaultController controller;

    controller = new AVACRLProtractedDefaultController(classStr(AVACRLProtractedDefaultService),
                                       methodStr(AVACRLProtractedDefaultService, startOperation),
                                       SysOperationExecutionMode::Synchronous);

    controller.startOperation();
}

/// <summary>
/// Returns default classDescription
/// </summary>
/// <returns>ClassDescription</returns>
protected ClassDescription defaultCaption()
{
    return "@NDX:NXACRLProtractedDefault";
}
